"""RoboPaint robot trajectory and calibration. Uses only public Robot API and RGB/depth."""
import sys, json, math, time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); r=Robot(); Q=[0,1,0,0]

def obs(label='view'):
    o=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True);o.save(str(OUT/label))
    for k,v in o.last.items():Image.fromarray(v).save(OUT/f'{label}_{k}.png')
    return o

def send(P,label='motion'):
    P=np.asarray(P); results=[]
    for start in range(0,len(P),190):
        chunk=P[start:start+190]; before=r.status(); idx=before['calls']
        np.save(OUT/f'command_{idx:04d}.npy',chunk)
        try:res=r.submit('ee_pose',chunk,dt=.05,cameras=['canvas_cam','practice_cam'],video='none',note=label)
        except Exception:
            r.wait_ready();after=r.status()
            if after['control_steps']==before['control_steps']:res=r.submit('ee_pose',chunk,dt=.05,cameras=['canvas_cam','practice_cam'],video='none',note=label)
            else: raise
        res.save(str(OUT/f'run_{idx:04d}'));results.append(res)
        print(label,idx,res.meta.get('control_steps_chunk'),res.meta.get('plan'),flush=True)
    return results[-1]

def move(x,y,z,speed=.06):
    o=r.get_obs(cameras=[]);p=np.array(o.meta['proprio']['now'][7:10]);end=np.array([x,y,z]);n=max(10,int(np.linalg.norm(p-end)/speed/.05))
    return send([list(p+(end-p)*t)+Q for t in np.linspace(0,1,n)]+[list(end)+Q]*10,'travel')

def line(points,speed=.012,label='stroke'):
    rows=[]
    for a,b in zip(points[:-1],points[1:]):
        a=np.array(a);b=np.array(b);n=max(1,math.ceil(np.linalg.norm(b-a)/speed/.05))
        rows.extend([list(a+(b-a)*t)+Q for t in np.linspace(0,1,n+1)[1:]])
    return send(rows,label)

def dip():
    move(-.10,.152,.07);move(-.10,.152,.023,speed=.02);move(-.10,.152,.07,speed=.03)

if __name__=='__main__':
    if sys.argv[1]=='park':move(-.24,0,.15);obs('park')
    elif sys.argv[1]=='dip':dip();obs('dip')
