import cv2,json,numpy as np
from scipy.ndimage import distance_transform_edt
from PIL import Image
S=[np.array(x,float)/2 for x in json.load(open('/app/output/strokes.json'))]
target=cv2.imread('/app/target.png',0)[::2,::2]<100
far=distance_transform_edt(~target)>2.25

def render(stroke):
 im=np.zeros((512,512),np.uint8)
 for a,b in zip(stroke[:-1],stroke[1:]):
  # tangent-sided cone plus round caps, supersampling fixedpoint
  delta=b[:2]-a[:2];n=np.linalg.norm(delta)
  if n>0:
   perp=np.array([-delta[1],delta[0]])/n
   pts=np.array([a[:2]+perp*a[2],b[:2]+perp*b[2],b[:2]-perp*b[2],a[:2]-perp*a[2]])
   cv2.fillConvexPoly(im,np.round(pts*16).astype(np.int32),1,shift=4)
  for x,y,r in [a,b]:cv2.circle(im,(round(x*16),round(y*16)),round(r*16),1,-1,shift=4)
 return im>0
R=[render(x) for x in S]
def loss(im):
 return np.count_nonzero(target&~im)+1.12*np.count_nonzero(im&~target)+2*np.count_nonzero(im&far)
for step in [2,1,.5,.25]:
 for it in range(3):
  nchanges=0
  for i,s in enumerate(S):
   other=np.logical_or.reduce([x for j,x in enumerate(R) if j!=i]);best=loss(other|R[i])
   for j in range(len(s)):
    for k in range(3):
     old=s[j,k];bv=old
     for d in [-step,step]:
      s[j,k]=old+d
      if s[j,2]<.4:continue
      new=render(s);v=loss(other|new)
      if v<best: best=v;bv=old+d;bestim=new
     s[j,k]=bv
     if bv!=old:R[i]=bestim;nchanges+=1
  print(step,it,nchanges,loss(np.logical_or.reduce(R)),flush=True)
  if not nchanges:break
json.dump([(s*2).tolist() for s in S],open('/app/output/strokes_opt.json','w'))
p=np.logical_or.reduce(R);out=np.full((512,512,3),245,np.uint8);out[target]=[175,175,175];out[p&target]=20;out[p&~target]=[220,60,50];Image.fromarray(out).resize((1024,1024)).save('/app/output/optimized.png')
print('iou',np.sum(p&target)/np.sum(p|target),'far',np.sum(p&far)/np.sum(target))
